<script setup lang="ts">
import { ref } from 'vue'
const login=ref(''),password=ref(''),error=ref(''),loading=ref(false)
async function submit(){loading.value=true;error.value='';try{const r=await fetch(`${import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1'}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({login:login.value,password:password.value})});const p=await r.json();if(!r.ok||!p.success)throw new Error(p.message??'Login gagal.');sessionStorage.setItem('tb_token',p.data.token);sessionStorage.setItem('tb_user',JSON.stringify(p.data.user));const role=p.data.user.role;window.location.href=['admin','staff'].includes(role)?'/admin':role==='kader'?'/kader':'/app'}catch(e){error.value=e instanceof Error?e.message:'Login gagal.'}finally{loading.value=false}}
</script>
<template><main class="login-page"><form @submit.prevent="submit"><img src="/icons/monitoring-tb.png" alt="Empati TB" class="login-icon"><div class="brand">Empati<span>TB</span></div><h1>Masuk Empati TB</h1><p>Masukkan username/email untuk petugas, atau nomor HP untuk pasien dan kader.</p><label>Username, Email, atau No. HP<input v-model="login" autocomplete="username" required></label><label>Password / PIN<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="login-error">{{error}}</p><button :disabled="loading">{{loading?'Memproses…':'Masuk'}}</button></form></main></template>
